import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 7.8
.target sm_89
.address_size 64

.visible .entry matmul_kernel(
    .param .u64 param_A,
    .param .u64 param_B,
    .param .u64 param_C,
    .param .u32 param_M,
    .param .u32 param_N,
    .param .u32 param_K
)
{
    .reg .u32 %r<32>;
    .reg .u64 %rd<32>;
    .reg .f32 %f<16>;
    .reg .pred %p<8>;

    ld.param.u64 %rd1, [param_A];
    ld.param.u64 %rd2, [param_B];
    ld.param.u64 %rd3, [param_C];
    ld.param.u32 %r4, [param_M];
    ld.param.u32 %r5, [param_N];
    ld.param.u32 %r6, [param_K];

    mov.u32 %r1, %ctaid.y;
    mov.u32 %r2, %ntid.y;
    mov.u32 %r3, %tid.y;
    mad.lo.u32 %r7, %r1, %r2, %r3;

    mov.u32 %r8, %ctaid.x;
    mov.u32 %r9, %ntid.x;
    mov.u32 %r10, %tid.x;
    mad.lo.u32 %r11, %r8, %r9, %r10;

    setp.ge.u32 %p1, %r7, %r4;
    @%p1 ret;
    setp.ge.u32 %p2, %r11, %r5;
    @%p2 ret;

    cvt.u64.u32 %rd4, %r7;
    cvt.u64.u32 %rd5, %r5;
    cvt.u64.u32 %rd6, %r11;

    mul.lo.u64 %rd7, %rd4, %rd5;
    add.u64 %rd8, %rd7, %rd6;
    shl.b64 %rd9, %rd8, 2;
    add.u64 %rd10, %rd3, %rd9;

    cvt.u64.u32 %rd11, %r6;
    mul.lo.u64 %rd12, %rd4, %rd11;
    shl.b64 %rd13, %rd12, 2;
    add.u64 %rd14, %rd1, %rd13;

    mov.u32 %r12, 0;
    mov.f32 %f1, 0f00000000;

LOOP:
    setp.ge.u32 %p3, %r12, %r6;
    @%p3 bra DONE;

    cvt.u64.u32 %rd15, %r12;
    shl.b64 %rd16, %rd15, 2;
    add.u64 %rd17, %rd14, %rd16;
    ld.global.f32 %f2, [%rd17];

    mul.lo.u64 %rd18, %rd15, %rd5;
    add.u64 %rd19, %rd18, %rd6;
    shl.b64 %rd20, %rd19, 2;
    add.u64 %rd21, %rd2, %rd20;
    ld.global.f32 %f3, [%rd21];

    fma.rn.f32 %f1, %f2, %f3, %f1;
    add.u32 %r12, %r12, 1;
    bra LOOP;

DONE:
    st.global.f32 [%rd10], %f1;
    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    _get_ptx_module().function("matmul_kernel")

class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()

    def forward(self, A, B):
        M = A.shape[0]
        K = A.shape[1]
        N = B.shape[1]
        C = torch.empty((M, N), device=A.device, dtype=A.dtype)
        module = _get_ptx_module()
        module.launch(
            "matmul_kernel",
            grid=((N + 15) // 16, (M + 15) // 16, 1),
            block=(16, 16, 1),
            arguments=[A, B, C, u32(M), u32(N), u32(K)],
            shared_memory=0,
            stream=torch.cuda.current_stream(A.device),
        )
        return C

